#pragma once

#include <cstddef>
#include <cmath>
#include <immintrin.h>
#include <omp.h>

namespace baseline {

inline std::size_t idx(const std::size_t i, const std::size_t j, const std::size_t n) {
    return i * n + j;
}

inline void gauss_seidel_poisson_sweep(
    double* psi, const double* omega, const std::size_t n,
    const double h, const std::size_t sweeps = 1) {
    const double h2 = h * h;
    constexpr std::size_t VL = 4; // AVX double width

    for (std::size_t sweep = 0; sweep < sweeps; ++sweep) {
        for (std::size_t color = 0; color < 2; ++color) { // 0 = red, 1 = black
#pragma omp parallel for
            for (std::size_t i = 1; i + 1 < n; ++i) {
                double* psi_i   = psi + i * n;
                double* psi_ip1 = psi + (i + 1) * n;
                double* psi_im1 = psi + (i - 1) * n;
                const double* omega_i = omega + i * n;

                std::size_t j = 1;
                const std::size_t max_j = n - 2;
                const std::size_t simd_end = max_j - VL + 1;

                // Vectorized part
                for (; j <= simd_end; j += VL) {
                    // Load needed values
                    __m256d omega_v = _mm256_loadu_pd(omega_i + j);
                    __m256d up_v    = _mm256_loadu_pd(psi_ip1 + j);
                    __m256d down_v  = _mm256_loadu_pd(psi_im1 + j);
                    __m256d left_v  = _mm256_loadu_pd(psi_i + j - 1);
                    __m256d right_v = _mm256_loadu_pd(psi_i + j + 1);

                    __m256d sum = _mm256_add_pd(up_v, down_v);
                    sum = _mm256_add_pd(sum, left_v);
                    sum = _mm256_add_pd(sum, right_v);
                    __m256d h2_omega = _mm256_mul_pd(_mm256_set1_pd(h2), omega_v);
                    sum = _mm256_add_pd(sum, h2_omega);
                    __m256d new_v = _mm256_mul_pd(_mm256_set1_pd(0.25), sum);

                    // Old psi values for blending
                    __m256d old_v = _mm256_loadu_pd(psi_i + j);

                    // Build mask for selected color (red/black)
                    __m256i j_vec = _mm256_add_epi64(
                        _mm256_set1_epi64x(static_cast<long long>(j)),
                        _mm256_set1_epi64x(3) // _mm256_set_epi64x(3,2,1,0) gives [j, j+1, j+2, j+3]
                    );
                    // Actually we need [j, j+1, j+2, j+3] low-to-high:
                    __m256i j_idx = _mm256_add_epi64(
                        _mm256_set1_epi64x(static_cast<long long>(j)),
                        _mm256_set_epi64x(3, 2, 1, 0)
                    );
                    __m256i parity_j = _mm256_and_si256(j_idx, _mm256_set1_epi64x(1LL));
                    __m256i parity_i = _mm256_set1_epi64x(static_cast<long long>(i & 1));
                    __m256i parity_sum = _mm256_xor_si256(parity_i, parity_j);
                    __m256i target = _mm256_set1_epi64x(static_cast<long long>(color));
                    __m256i mask_eq = _mm256_cmpeq_epi64(parity_sum, target);
                    __m256d mask_d = _mm256_castsi256_pd(mask_eq);

                    __m256d res_v = _mm256_blendv_pd(old_v, new_v, mask_d);
                    _mm256_storeu_pd(psi_i + j, res_v);
                }

                // Scalar remainder
                for (; j <= max_j; ++j) {
                    if (((i + j) & 1) == color) {
                        std::size_t c = idx(i, j, n);
                        psi[c] = 0.25 * (
                            psi[idx(i + 1, j, n)] + psi[idx(i - 1, j, n)] +
                            psi[idx(i, j - 1, n)] + psi[idx(i, j + 1, n)] +
                            h2 * omega[c]
                        );
                    }
                }
            }
        }
    }
}

inline void vorticity_transport_step(
    double* omega_new,
    const double* omega,
    const double* psi,
    const std::size_t n,
    const double h,
    const double dt,
    const double re) {
    const double inv_2h = 0.5 / h;
    const double inv_h2 = 1.0 / (h * h);
    const double inv_re = 1.0 / re;
    constexpr std::size_t VL = 4; // AVX double width

#pragma omp parallel for collapse(2)
    for (std::size_t i = 1; i + 1 < n; ++i) {
        const double* psi_i   = psi + i * n;
        const double* psi_ip1 = psi + (i + 1) * n;
        const double* psi_im1 = psi + (i - 1) * n;
        const double* omega_i   = omega + i * n;
        const double* omega_ip1 = omega + (i + 1) * n;
        const double* omega_im1 = omega + (i - 1) * n;
        double* omega_new_i = omega_new + i * n;

        std::size_t j = 1;
        const std::size_t max_j = n - 2;
        const std::size_t simd_end = max_j - VL + 1;

        // Vectorized part
        for (; j <= simd_end; j += VL) {
            // Load psi values
            __m256d psi_i_jm1 = _mm256_loadu_pd(psi_i + j - 1);
            __m256d psi_i_jp1 = _mm256_loadu_pd(psi_i + j + 1);
            __m256d psi_ip1_j = _mm256_loadu_pd(psi_ip1 + j);
            __m256d psi_im1_j = _mm256_loadu_pd(psi_im1 + j);

            // Load omega values
            __m256d omega_i_j   = _mm256_loadu_pd(omega_i + j);
            __m256d omega_i_jm1 = _mm256_loadu_pd(omega_i + j - 1);
            __m256d omega_i_jp1 = _mm256_loadu_pd(omega_i + j + 1);
            __m256d omega_ip1_j = _mm256_loadu_pd(omega_ip1 + j);
            __m256d omega_im1_j = _mm256_loadu_pd(omega_im1 + j);

            // Compute u = (psi[i,j+1] - psi[i,j-1]) * inv_2h
            __m256d diff_psi_y = _mm256_sub_pd(psi_i_jp1, psi_i_jm1);
            __m256d u = _mm256_mul_pd(diff_psi_y, _mm256_set1_pd(inv_2h));

            // Compute v = -(psi[i+1,j] - psi[i-1,j]) * inv_2h
            __m256d diff_psi_x = _mm256_sub_pd(psi_ip1_j, psi_im1_j);
            __m256d v = _mm256_mul_pd(_mm256_set1_pd(-inv_2h), diff_psi_x);

            // Compute domega/dx = (omega[i+1,j] - omega[i-1,j]) * inv_2h
            __m256d domega_dx = _mm256_mul_pd(
                _mm256_sub_pd(omega_ip1_j, omega_im1_j),
                _mm256_set1_pd(inv_2h)
            );

            // Compute domega/dy = (omega[i,j+1] - omega[i,j-1]) * inv_2h
            __m256d domega_dy = _mm256_mul_pd(
                _mm256_sub_pd(omega_i_jp1, omega_i_jm1),
                _mm256_set1_pd(inv_2h)
            );

            // Advection term
            __m256d advection = _mm256_add_pd(
                _mm256_mul_pd(u, domega_dx),
                _mm256_mul_pd(v, domega_dy)
            );

            // Laplacian: (ωi+1,j + ωi-1,j + ωi,j+1 + ωi,j-1 - 4*ωi,j) * inv_h2
            __m256d omega_sum = _mm256_add_pd(
                _mm256_add_pd(omega_ip1_j, omega_im1_j),
                _mm256_add_pd(omega_i_jp1, omega_i_jm1)
            );
            __m256d laplacian = _mm256_mul_pd(
                _mm256_sub_pd(omega_sum, _mm256_mul_pd(omega_i_j, _mm256_set1_pd(4.0))),
                _mm256_set1_pd(inv_h2)
            );

            // Forward Euler update
            __m256d tmp = _mm256_sub_pd(
                _mm256_mul_pd(laplacian, _mm256_set1_pd(inv_re)),
                advection
            );
            __m256d omega_new_v = _mm256_add_pd(
                omega_i_j,
                _mm256_mul_pd(tmp, _mm256_set1_pd(dt))
            );

            _mm256_storeu_pd(omega_new_i + j, omega_new_v);
        }

        // Scalar remainder
        for (; j <= max_j; ++j) {
            std::size_t c = idx(i, j, n);
            // Reconstruct velocities
            double u = (psi_i[j + 1] - psi_i[j - 1]) * inv_2h;
            double v = -(psi_ip1[j] - psi_im1[j]) * inv_2h;

            // Central differences for omega
            double domega_dx = (omega_ip1[j] - omega_im1[j]) * inv_2h;
            double domega_dy = (omega_i[j + 1] - omega_i[j - 1]) * inv_2h;
            double advection = u * domega_dx + v * domega_dy;

            // Laplacian
            double laplacian_omega = (
                omega_ip1[j] + omega_im1[j] +
                omega_i[j + 1] + omega_i[j - 1] -
                4.0 * omega_i[j]
            ) * inv_h2;

            omega_new[c] = omega_i[j] + dt * (inv_re * laplacian_omega - advection);
        }
    }
}

}  // namespace baseline

